-- The service does not use these objects. The terms of a user are in
-- contract_terms. The drops delete the rows and values of the objects.
-- lock_timeout makes a busy table fail the migrate step instead of queueing
-- the queries of the running release. Keep user_settings last: the request
-- path reads it. Do not edit this file after release: SQLx checks its hash.
SET LOCAL lock_timeout = '5s';
DROP TABLE "session";
DROP TABLE "verification";
ALTER TABLE user_settings
  DROP COLUMN margin_cents_kwh,
  DROP COLUMN transfer_day_cents_kwh,
  DROP COLUMN transfer_night_cents_kwh,
  DROP COLUMN tax_cents_kwh,
  DROP COLUMN vat_percent,
  DROP COLUMN night_start_hour,
  DROP COLUMN night_end_hour;
